      FL_TRY(compiler_flang_nachalo_spiska(ctx, hvost, fl_number(skolko.as.number - 1.0), &fl_t116, error));
      fl_value fl_t117 = fl_nothing();
      FL_TRY(fl_concat(ctx, golova, fl_t116, &fl_t117, error));
